// Дані беремо з webhook як є, без перетворень.
// Перевіряємо лише, що заповнені поля, потрібні для подальшої роботи.
const body = $('KeyCRM Webhook').first().json.body || {};
const str = (v) => (v === null || v === undefined) ? '' : String(v);
const ctx = {
  cardId: str(body.id),             // ID картки KeyCRM -> keycrm_id у Data Table і PUT /pipelines/cards/{id}
  name: str(body.contact_name),     // -> Name
  phone: str(body.contact_phone),   // -> Phone (у форматі, як прийшов із KeyCRM)
  title: str(body.title),
  triedSessionIds: [],
  attempt: 0,
  reason: '',
};
const missing = [];
if (!ctx.cardId.trim()) missing.push('id');
if (!ctx.name.trim()) missing.push('contact_name');
if (!ctx.phone.trim()) missing.push('contact_phone');
ctx.valid = missing.length === 0;
if (!ctx.valid) ctx.reason = "У webhook не заповнені обов'язкові поля: " + missing.join(', ');
return [{ json: ctx }];

// Рядки Data Table: { id (автоінкремент), createdAt, updatedAt, ...колонки }. Порожній результат = [{}].
const rows = (items) => items.map((i) => i.json).filter((j) => j && j.id !== undefined && j.id !== null);
const cfg = $('Конфіг').first().json;
const ctx = { ...$('Перевірка полів webhook').first().json };
const recs = rows($input.all()).sort((a, b) => a.id - b.id);
const active = recs.filter((r) => r.registration_status !== 'Cancelled');

if (active.length === 0) {
  if (recs.length > 0) {
    ctx.decision = 'manual';
    ctx.reason = 'Для цього KeyCRM ID є лише скасоване бронювання (Cancelled) — автоматично не перебронюємо';
  } else {
    ctx.decision = 'book';                        // нового кандидата бронюємо
  }
  return [{ json: ctx }];
}

const mine = active[0];
const sync = mine.keycrm_sync || '';
const sessionId = mine.session_id || '';
const ageMin = (Date.now() - new Date(mine.createdAt).getTime()) / 60000;
ctx.participantId = mine.id;
ctx.sessionId = sessionId;

if (sync === 'Synced') {
  ctx.decision = 'skip'; ctx.reason = 'Кандидат уже заброньований, картку KeyCRM оновлено раніше';
} else if (!sessionId) {
  ctx.decision = 'manual'; ctx.reason = "Запис учасника без прив'язаної сесії";
} else if (sync !== 'Failed' && ageMin < Number(cfg.PENDING_GRACE_MINUTES)) {
  ctx.decision = 'skip'; ctx.reason = 'Бронювання щойно створене іншим запуском (повторний webhook)';
} else {
  ctx.decision = 'verify';  // бронювання є, KeyCRM не оновлено -> підтверджуємо місце і повторюємо оновлення
}
return [{ json: ctx }];

const ctx = { ...$input.first().json };
// Сесія без вільних місць не витрачає спробу (як і раніше, коли такі сесії відсіював фільтр Airtable).
if (ctx.skipAttemptCount) ctx.skipAttemptCount = false;
else ctx.attempt = (ctx.attempt || 0) + 1;
ctx.triedSessionIds = ctx.triedSessionIds || [];
ctx.participantId = null;
ctx.sessionId = null;
return { json: ctx };

// Рядки Data Table: { id (автоінкремент), createdAt, updatedAt, ...колонки }. Порожній результат = [{}].
const rows = (items) => items.map((i) => i.json).filter((j) => j && j.id !== undefined && j.id !== null);
const cfg = $('Конфіг').first().json;
const ctx = { ...$('Спроба бронювання').first().json };
const minStart = Date.now() + Number(cfg.MIN_LEAD_MINUTES || 0) * 60000;
const list = rows($input.all())
  .filter((r) => r.session_id && r.start_date && new Date(r.start_date).getTime() > minStart)
  .filter((r) => !ctx.triedSessionIds.includes(r.session_id))
  .sort((a, b) => new Date(a.start_date) - new Date(b.start_date) || a.id - b.id);

if (ctx.attempt > Number(cfg.MAX_BOOKING_ATTEMPTS) || list.length === 0) {
  ctx.sessionFound = false;
  ctx.reason = list.length === 0
    ? 'Немає відкритих майбутніх сесій з вільними місцями'
    : `Вичерпано спроби бронювання (${cfg.MAX_BOOKING_ATTEMPTS}) — місця розібрали паралельні запити`;
} else {
  ctx.sessionFound = true;
  ctx.sessionId = list[0].session_id;
}
return { json: ctx };

// Рядки Data Table: { id (автоінкремент), createdAt, updatedAt, ...колонки }. Порожній результат = [{}].
const rows = (items) => items.map((i) => i.json).filter((j) => j && j.id !== undefined && j.id !== null);
const cfg = $('Конфіг').first().json;
const ctx = { ...$('Вибір найближчої сесії').first().json };
const s = rows($('DT: повторна перевірка сесії').all())[0] || {};
const count = rows($input.all()).length;
const max = Number(s.max_participants) > 0 ? Number(s.max_participants) : Number(cfg.DEFAULT_MAX_PARTICIPANTS);
const available = Math.max(0, max - count);                                   // Available Seats = MAX(0, Max - Current)
const ok = s.status === 'Open' && available > 0 && s.start_date && new Date(s.start_date).getTime() > Date.now();
ctx.seatOk = !!ok;
if (!ok) {
  ctx.triedSessionIds = [...ctx.triedSessionIds, ctx.sessionId];
  ctx.skipAttemptCount = available === 0 && s.status === 'Open';             // сесія без місць — не спроба бронювання
}
return { json: ctx };

const ctx = { ...$('Місце ще вільне?').first().json };
const rec = $input.first().json;
ctx.participantId = rec.id;
ctx.createdTime = rec.createdAt;
return { json: ctx };

// Рядки Data Table: { id (автоінкремент), createdAt, updatedAt, ...колонки }. Порожній результат = [{}].
const rows = (items) => items.map((i) => i.json).filter((j) => j && j.id !== undefined && j.id !== null);
const ctx = { ...$('Пауза перед перевіркою гонки').first().json };
const active = rows($input.all())
  .filter((r) => r.registration_status !== 'Cancelled').sort((a, b) => a.id - b.id);
const mine = active.find((r) => r.id === ctx.participantId);
if (!mine) {
  ctx.dedup = 'gone';
  ctx.reason = 'Запис учасника вже видалено іншим запуском';
} else if (active[0].id !== ctx.participantId) {
  ctx.dedup = 'duplicate';
  ctx.reason = `Дубль: основний запис ${active[0].id}`;
} else {
  ctx.dedup = 'primary';
  ctx.sessionId = mine.session_id || ctx.sessionId;
}
return { json: ctx };

// Рядки Data Table: { id (автоінкремент), createdAt, updatedAt, ...колонки }. Порожній результат = [{}].
const rows = (items) => items.map((i) => i.json).filter((j) => j && j.id !== undefined && j.id !== null);
const cfg = $('Конфіг').first().json;
const ctx = { ...$('Дедуплікація').first().json };
const s = rows($input.all())[0];
ctx.session = s ? {
  id: s.session_id,
  name: s.session_name || '',
  start: s.start_date || null,
  max: Number(s.max_participants) > 0 ? Number(s.max_participants) : Number(cfg.DEFAULT_MAX_PARTICIPANTS),
  status: s.status || '',
} : { id: ctx.sessionId, name: '', start: null, max: 0, status: 'Missing' };
return { json: ctx };

// Рядки Data Table: { id (автоінкремент), createdAt, updatedAt, ...колонки }. Порожній результат = [{}].
const rows = (items) => items.map((i) => i.json).filter((j) => j && j.id !== undefined && j.id !== null);
const ctx = { ...$('Дані сесії').first().json };
const active = rows($input.all())
  .filter((r) => r.registration_status !== 'Cancelled')
  .filter((r) => r.session_id === ctx.session.id)
  .sort((a, b) => a.id - b.id);
const rank = active.findIndex((r) => r.id === ctx.participantId) + 1;
const startOk = ctx.session.start && new Date(ctx.session.start).getTime() > Date.now();
ctx.rank = rank;
ctx.activeCount = active.length;
ctx.seatConfirmed = rank > 0 && rank <= ctx.session.max && startOk && ctx.session.status !== 'Closed';
ctx.sessionNowFull = ctx.seatConfirmed && active.length >= ctx.session.max && ctx.session.status === 'Open';
if (!ctx.seatConfirmed) {
  ctx.reason = `Місце не підтверджено: позиція ${rank} при ліміті ${ctx.session.max}` + (startOk ? '' : ' (сесія вже почалась)');
  ctx.triedSessionIds = [...(ctx.triedSessionIds || []), ctx.session.id];
}
return { json: ctx };

const cfg = $('Конфіг').first().json;
const ctx = { ...$input.first().json };
const start = DateTime.fromISO(ctx.session.start, { zone: 'utc' });
if (!start.isValid) throw new Error('Некоректна Start Date сесії: ' + ctx.session.start);
const local = start.setZone(cfg.TIMEZONE);
const type = String(cfg.INTERVIEW_FIELD_TYPE || 'datetime').toLowerCase();
let value;
if (type === 'datetime') value = start.toUTC().toFormat("yyyy-LL-dd'T'HH:mm:ss.SSS'000Z'"); // ISO 8601 UTC, як у документації KeyCRM
else if (type === 'date') value = local.toFormat('yyyy-LL-dd');
else value = local.toFormat('dd.LL.yyyy HH:mm');                                            // текстове поле: київський час
ctx.interviewKyiv = local.toFormat('dd.LL.yyyy HH:mm') + ' (' + cfg.TIMEZONE + ')';
ctx.keycrmBody = {
  status_id: Number(cfg.TARGET_STATUS_ID),
  custom_fields: [{ uuid: cfg.INTERVIEW_FIELD_UUID, value }],
};
return { json: ctx };

const ctx = { ...$('Дані для KeyCRM').first().json };
const e = $input.first().json.error ?? $input.first().json;
ctx.errorText = (typeof e === 'string' ? e : (e.message || '') + (e.description ? ' | ' + e.description : '') || JSON.stringify(e)).slice(0, 2000);
ctx.errorText = new Date().toISOString() + ' KeyCRM PUT: ' + ctx.errorText;
return { json: ctx };
